const markdown = $input.all()[0]?.json?.output?.[1]?.text || '';

function formatMarkdownToHTML(text) {
    let html = text;

    // 1. ERST Headings ersetzen (längste zuerst!)
    html = html.replace(/^##### (.*$)/gm, '<h5 class="h5">$1</h5>');
    html = html.replace(/^#### (.*$)/gm, '<h4 class="h4">$1</h4>');
    html = html.replace(/^### (.*$)/gm, '<h3 class="h3">$1</h3>');
    html = html.replace(/^## (.*$)/gm, '<h2 class="h2">$1</h2>');
    html = html.replace(/^# (.*$)/gm, '<h1 class="h1">$1</h1>');

    // 2. Bold/Strong Text
    html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');

    // 3. Listen formatieren (vor <br> Ersetzung!)
    html = html.replace(/^- (.*$)/gm, '<li class="list-item">$1</li>');

    // 4. Zeilenschaltungen zu <br>
    html = html.replace(/\n/g, '<br>');

    // 5. Listen in <ul> Container wrappen
    html = html.replace(/(<li class="list-item">.*?<\/li>(<br>)*)+/g, function(match) {
        return '<ul class="event-list">' + match.replace(/<br>/g, '') + '</ul>';
    });

    // 6. Doppelte <br> nach Headings entfernen
    html = html.replace(/(<\/h[1-6]>)<br>/g, '$1');

    // 7. Mehrfache <br> reduzieren
    html = html.replace(/(<br>){3,}/g, '<br><br>');

    return html;
}

// CSS Styles hinzufügen für bessere Formatierung
const styledHTML = `
<div class="markdown-content">
    <style>
        .markdown-content {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            line-height: 1.6;
            color: #333;
        }
        .markdown-content .h1 {
            color: #667eea;
            font-size: 1.8em;
            margin: 20px 0 15px 0;
            border-bottom: 2px solid #667eea;
            padding-bottom: 8px;
        }
        .markdown-content .h2 {
            color: #764ba2;
            font-size: 1.5em;
            margin: 18px 0 12px 0;
            border-bottom: 1px solid #e9ecef;
            padding-bottom: 5px;
        }
        .markdown-content .h3 {
            color: #495057;
            font-size: 1.3em;
            margin: 15px 0 10px 0;
        }
        .markdown-content .h4 {
            color: #6c757d;
            font-size: 1.1em;
            margin: 12px 0 8px 0;
            font-weight: 600;
        }
        .markdown-content .event-list {
            margin: 10px 0;
            padding-left: 0;
            list-style: none;
        }
        .markdown-content .list-item {
            margin: 8px 0;
            padding: 8px 12px;
            background: #f8f9fa;
            border-left: 3px solid #667eea;
            border-radius: 0 5px 5px 0;
        }
        .markdown-content strong {
            color: #495057;
            font-weight: 600;
        }
    </style>
    ${formatMarkdownToHTML(markdown)}
</div>
`;

// IMPORTANT FIX: Pass through the original JSON data and add the new 'html' property
// This ensures userId, location, etc., are not lost.
const originalItemJson = $input.all()[0]?.json; // Get the full JSON from the input item

return [{
  json: {
    ...originalItemJson, // Spread operator to include all existing properties (like userId)
    html: styledHTML      // Add the newly generated HTML
  }
}];
